MANIFEST = json.loads("{\"name\":\"sendhog\",\"version\":\"0.3.0\",\"baseUrl\":\"https://app.sendhog.com\",\"description\":\"SendHog public API and provider-shaped SDK subset. Own bearer authentication; not upstream wire/auth emulation. Sending remains operationally gated.\",\"auth\":{\"scheme\":\"bearer\",\"header\":\"Authorization\",\"keyPrefix\":\"sh_\",\"scopes\":[\"email.send\",\"email.read\",\"webhooks.manage\"]},\"methods\":[{\"name\":\"sendBulk\",\"http\":{\"method\":\"POST\",\"path\":\"/v1/send/bulk\"},\"request\":\"BulkSendRequest\",\"response\":\"BulkSendResponse\",\"scope\":\"email.send\",\"summary\":\"Send one personalized email per recipient using a published template. Waits for SES acceptance, returns ordered individual outcomes. Idempotency-Key required; never automatically retries email.\",\"availability\":\"implemented\"},{\"name\":\"getBulk\",\"http\":{\"method\":\"GET\",\"path\":\"/v1/send/bulk/{id}\"},\"response\":\"BulkSendResponse\",\"scope\":\"email.send\",\"summary\":\"Inspect outcomes from a bulk send in the key domain without resending.\",\"availability\":\"implemented\"},{\"name\":\"messageEvents\",\"http\":{\"method\":\"GET\",\"path\":\"/v1/messages/{id}/events\"},\"query\":\"EventQuery\",\"response\":\"EventList\",\"scope\":\"email.read\",\"summary\":\"Read retained email events for an owned message, newest first. Events are retained for 30 days.\",\"availability\":\"implemented\"},{\"name\":\"getRawMessage\",\"http\":{\"method\":\"GET\",\"path\":\"/v1/messages/{id}/raw\"},\"response\":\"RawMessage\",\"responseContentType\":\"message/rfc822\",\"scope\":\"email.read\",\"summary\":\"Download the retained original inbound email including attachments. Native HTTP streaming download, not a JSON SDK method.\",\"availability\":\"implemented\"},{\"name\":\"createWebhook\",\"http\":{\"method\":\"POST\",\"path\":\"/v1/webhooks\"},\"request\":\"CreateWebhookRequest\",\"response\":\"CreatedWebhook\",\"scope\":\"webhooks.manage\",\"summary\":\"Register a public HTTPS endpoint for signed email events. Returns the signing secret once.\",\"availability\":\"implemented\"},{\"name\":\"listWebhooks\",\"http\":{\"method\":\"GET\",\"path\":\"/v1/webhooks\"},\"response\":\"WebhookList\",\"scope\":\"webhooks.manage\",\"summary\":\"List domain-owned webhooks without secrets.\",\"availability\":\"implemented\"},{\"name\":\"deleteWebhook\",\"http\":{\"method\":\"DELETE\",\"path\":\"/v1/webhooks/{id}\"},\"response\":\"DeletedWebhook\",\"scope\":\"webhooks.manage\",\"summary\":\"Delete a domain-owned webhook and cancel pending deliveries.\",\"availability\":\"implemented\"},{\"name\":\"send\",\"http\":{\"method\":\"POST\",\"path\":\"/v1/send\"},\"request\":\"SendRequest\",\"response\":\"SendResponse\",\"scope\":\"email.send\",\"summary\":\"Send inline subject/text/html or a published domain-scoped template ID/slug with variables. Verified domains receive automatic sending approval; account limits, disable controls and normal dispatch safeguards apply.\",\"availability\":\"gated\"},{\"name\":\"listMessages\",\"http\":{\"method\":\"GET\",\"path\":\"/v1/messages\"},\"query\":\"ListMessagesQuery\",\"response\":\"MessageList\",\"scope\":\"email.read\",\"summary\":\"List retained email metadata and text in the key's domain, with a stable forward cursor.\",\"availability\":\"implemented\"},{\"name\":\"getMessage\",\"http\":{\"method\":\"GET\",\"path\":\"/v1/messages/{id}\"},\"response\":\"Message\",\"scope\":\"email.read\",\"summary\":\"Read one retained message in the key's domain. A foreign or missing ID returns 404.\",\"availability\":\"implemented\"}],\"providers\":[{\"id\":\"sendhog\",\"name\":\"SendHog\",\"jsClass\":\"SendHog\",\"pythonClass\":\"SendHog\",\"request\":\"SendRequest\",\"pythonRequest\":\"SendPythonRequest\",\"response\":\"SendResponse\",\"jsMethod\":\"send\",\"pythonMethod\":\"send\",\"format\":\"native\",\"source\":\"https://sendhog.com/docs/api/\",\"note\":\"Default: send(message) with inline subject/text/html OR template:{id,variables,version?} referencing a published SendHog domain template. Returns id/created_at directly. Optional cc/bcc/replyTo (Python reply_to). messages.list/get reads retained mail. No command objects, React node payloads or data/error wrapper.\"},{\"id\":\"ses\",\"name\":\"Amazon SES\",\"jsClass\":\"SESv2Client\",\"pythonClass\":\"SESv2Client\",\"request\":\"SesSendRequest\",\"response\":\"SesSendResponse\",\"pythonResponse\":\"SesPythonSendResponse\",\"jsMethod\":\"send\",\"pythonMethod\":\"send_email\",\"format\":\"ses\",\"replyField\":\"ReplyToAddresses\",\"source\":\"https://docs.aws.amazon.com/ses/latest/APIReference-V2/API_SendEmail.html\",\"note\":\"SES v2 Simple only. Use SendHog setup and SendEmailCommand; no AWS authentication. messages.list/get is a SendHog extension.\"},{\"id\":\"postmark\",\"name\":\"Postmark\",\"jsClass\":\"ServerClient\",\"pythonClass\":\"ServerClient\",\"request\":\"PostmarkSendRequest\",\"response\":\"PostmarkSendResponse\",\"pythonRequest\":\"PostmarkPythonSendRequest\",\"pythonResponse\":\"PostmarkPythonSendResponse\",\"jsMethod\":\"sendEmail\",\"pythonMethod\":\"outbound.send\",\"format\":\"postmark\",\"fields\":{\"from\":\"From\",\"to\":\"To\",\"cc\":\"Cc\",\"bcc\":\"Bcc\",\"replyTo\":\"ReplyTo\",\"subject\":\"Subject\",\"text\":\"TextBody\",\"html\":\"HtmlBody\"},\"pythonFields\":{\"from\":\"sender\",\"to\":\"to\",\"cc\":\"cc\",\"bcc\":\"bcc\",\"replyTo\":\"reply_to\",\"subject\":\"subject\",\"text\":\"text_body\",\"html\":\"html_body\"},\"source\":\"https://postmarkapp.com/developer/integration/official-libraries\",\"note\":\"Postmark JS ServerClient and current async Python outbound.send subset. Only the outbound transactional stream; no templates, tracking or attachments.\"},{\"id\":\"resend\",\"name\":\"Resend\",\"jsClass\":\"Resend\",\"pythonClass\":\"Resend\",\"request\":\"ResendSendRequest\",\"response\":\"ResendSendResponse\",\"pythonRequest\":\"ResendPythonSendRequest\",\"jsMethod\":\"emails.send\",\"pythonMethod\":\"Emails.send\",\"format\":\"resend\",\"fields\":{\"from\":\"from\",\"to\":\"to\",\"cc\":\"cc\",\"bcc\":\"bcc\",\"replyTo\":\"replyTo\",\"subject\":\"subject\",\"text\":\"text\",\"html\":\"html\"},\"pythonFields\":{\"from\":\"from\",\"to\":\"to\",\"cc\":\"cc\",\"bcc\":\"bcc\",\"replyTo\":\"reply_to\",\"subject\":\"subject\",\"text\":\"text\",\"html\":\"html\"},\"source\":\"https://resend.com/docs/api-reference/emails/send-email\",\"note\":\"JS returns data/error; Python returns the id dictionary. Supports inline html/text OR template:{id,variables,version?} with published SendHog IDs/slugs (not Resend-owned templates). No React rendering, scheduling, provider idempotency options or attachments.\"},{\"id\":\"sendgrid\",\"name\":\"SendGrid\",\"jsClass\":\"SendGridClient\",\"pythonClass\":\"SendGridAPIClient\",\"request\":\"SendGridSendRequest\",\"pythonRequest\":\"SendGridPythonSendRequest\",\"response\":\"SendGridResponse\",\"jsMethod\":\"send\",\"pythonMethod\":\"send\",\"format\":\"sendgrid\",\"fields\":{\"from\":\"from\",\"to\":\"to\",\"cc\":\"cc\",\"bcc\":\"bcc\",\"replyTo\":\"replyTo\",\"subject\":\"subject\",\"text\":\"text\",\"html\":\"html\"},\"source\":\"https://www.twilio.com/docs/sendgrid/api-reference/mail-send/mail-send\",\"note\":\"JS simple mail helper subset; Python raw dictionary with one personalization/envelope. JS returns response/body pair; Python returns status_code, headers, body. No multiple personalizations, bulk, templates or helper-object emulation.\"}],\"languages\":[{\"id\":\"node\",\"label\":\"JavaScript\",\"highlight\":\"javascript\"},{\"id\":\"typescript\",\"label\":\"TypeScript\",\"highlight\":\"typescript\"},{\"id\":\"python\",\"label\":\"Python\",\"highlight\":\"python\"},{\"id\":\"curl\",\"label\":\"cURL\",\"highlight\":\"bash\"}],\"limits\":{\"recipients\":50,\"bodyCharacters\":100000,\"automaticRetries\":0},\"receiving\":{\"js\":\"messages.list / messages.get\",\"python\":\"messages.list / messages.get\",\"kind\":\"SendHog extension\",\"note\":\"Reads retained metadata/text only. No SES/SendGrid inbox API is invented; upstream inbound webhook, attachment and MIME parity are not claimed.\"}}")
